package com.bank.core;

import java.util.Arrays;

public class BalanceComparator {
    // One-dimensional: element-by-element.
    public boolean sameDailyBalances(long[] a, long[] b) {
        return Arrays.equals(a, b);
    }
    // Nested (matrix of settlement amounts): recurse into sub-arrays.
    public boolean sameSettlementMatrix(long[][] a, long[][] b) {
        return Arrays.deepEquals(a, b);
    }
    // Readable rendering for logs.
    public String render(long[] a) { return Arrays.toString(a); }
    public String renderNested(long[][] a) { return Arrays.deepToString(a); }
}
