package com.bank.core;

import java.util.logging.*;

public class ArrayCompareDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BalanceComparator cmp = new BalanceComparator();

        long[] week1 = {100000, 95000, 97000, 90000};
        long[] week2 = {100000, 95000, 97000, 90000};

        // WRONG: identity comparisons.
        log.warning(() -> "week1 == week2 → " + (week1 == week2));
        log.warning(() -> "week1.equals(week2) → " + week1.equals(week2));

        // RIGHT: 1-D content comparison.
        log.info(() -> "Arrays.equals → " + cmp.sameDailyBalances(week1, week2)
                        + "  data=" + cmp.render(week1));

        long[][] settleA = {{50000, 25000}, {30000, 10000}};
        long[][] settleB = {{50000, 25000}, {30000, 10000}};

        // WRONG for nested: inner arrays compared by reference.
        log.warning(() -> "Arrays.equals (nested, wrong) → "
                        + java.util.Arrays.equals(settleA, settleB));
        // RIGHT for nested.
        log.info(() -> "Arrays.deepEquals → " + cmp.sameSettlementMatrix(settleA, settleB)
                        + "  data=" + cmp.renderNested(settleA));
    }
}
